// Identity: phone + date of birth -> name and address. Vendor: Verified (mocked only).
import { patientById, type Patient } from "../fixtures";
import { timedMock } from "./mock";
import type { AdapterResult, LookupContext } from "./types";

export const IDENTITY_SOURCE = "Verified";

export function lookupIdentity(ctx: LookupContext): AdapterResult<Patient> {
  // Verified stays mocked in every mode (CLAUDE.md).
  return timedMock(ctx, "identity", IDENTITY_SOURCE, () => {
    const p = patientById(ctx.patientId);
    // A match needs both phone and date of birth. Any doubt becomes a question for the patient.
    return p && p.dob === ctx.dob ? p : null;
  });
}
EOF
cat > coverage.ts <<'EOF'
// Coverage: insurance discovery + eligibility + copay. Vendor: Sohar Health.
import { coverageByPatient, type Coverage } from "../fixtures";
import { sandboxUnavailable, timedMock } from "./mock";
import { adapterMode, type AdapterResult, type LookupContext } from "./types";

export const COVERAGE_SOURCE = "Sohar";

export function discoverAndVerify(ctx: LookupContext, identityMatched: boolean): AdapterResult<Coverage> {
  if (adapterMode() === "sandbox" && !process.env.SOHAR_API_KEY) return sandboxUnavailable(COVERAGE_SOURCE);
  if (!identityMatched && ctx.now >= ctx.startedAt) {
    // Coverage runs on the matched identity; with no match there is nothing to verify.
    const r = timedMock<Coverage>(ctx, "coverage", COVERAGE_SOURCE, () => null);
    if (r.status !== "pending") return { ...r, status: "not_found", data: null, note: r.note ?? "No identity to verify" };
  }
  return timedMock(ctx, "coverage", COVERAGE_SOURCE, () => (ctx.patientId ? coverageByPatient[ctx.patientId] : null));
}
EOF
