        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        style={{ boxShadow: "0 4px 16px rgba(11,11,12,.12)", fontFamily: "var(--font-mono)", fontSize: 12, letterSpacing: ".12em", textTransform: "uppercase" }}
      >
        {open ? "Close demo" : "Demo"}
      </button>
    </div>
  );
}

