      text,
      ids,
      source: aiIds.length && ids.some((id) => aiIds.includes(id)) ? source : "picked",
      recordAnswers: answers,
    });
    setBusy(false);
    if (!r.ok) return setError(r.error ?? "Something went wrong.");
    router.push("/snapshot");
  }

  return (
    <>
