          <div className="card" role="alert" style={{ borderColor: "var(--danger)", background: "var(--danger-soft)" }}>
            <span style={{ fontSize: 15, fontWeight: 600 }}>If you&apos;re thinking about harming yourself, please reach out now.</span>
            <span style={{ fontSize: 15 }}>
              Call or text <a href="tel:988">988</a>, or call <a href="tel:911">911</a> if you&apos;re in danger. <a href="/crisis-resources" onClick={(e) => { e.preventDefault(); void act("safety", { answer: "yes" }).then(() => router.push("/crisis")); }}>Get support now</a>
            </span>
